    function eqLang() {
        var l = '';
        try { if (window.vcI18n && window.vcI18n._lang) l = window.vcI18n._lang; } catch (e) {}
        try { if (!l && window.mySimulation && window.mySimulation.lang) l = window.mySimulation.lang; } catch (e) {}
        try { if (!l && document.documentElement.lang) l = document.documentElement.lang; } catch (e) {}
        return String(l || 'en').toLowerCase().slice(0, 2);
    }

    function eqT(k) {
        try { if (window.mySimulation && typeof window.mySimulation.t === 'function') { var v = window.mySimulation.t(k); if (v && v !== k) return v; } } catch (e) {}
        return k;
    }

    // Known wrong-method answers per problem, from the teaching note exhibit 3. A method with full marks under the
    // 2 percent rule is named only in the closing debrief; the others are also named in the problem feedback.
    var METHODS = [
        [ { v: 13382.26, k: 'm_annual', full: true }, { v: 13498.59, k: 'm_continuous', full: true }, { v: 13000, k: 'm_simple' }, { v: 32071.35, k: 'm_rate_per_quarter' } ],
        [ { v: 1278.99, k: 'm_annual_pmt', full: true }, { v: 937.5, k: 'm_interest_only' } ],
        [ { v: 125, k: 'm_revenue_max' } ],
        [ { v: 141.42, k: 'm_ac_sqrt' } ],
        [ { v: 774.6, k: 'm_eoq_no2' } ],
        [ { v: 625, k: 'm_fc_price' } ],
        [ { v: 270000, k: 'm_loss_dropped' }, { v: 295000, k: 'm_loss_sign' } ],
        [ { v: 7200, k: 'm_cs_rect' } ]
    ];

    function detectMethod(idx, submitted) {
        var list = METHODS[idx] || [];
        var key = PROBLEMS[idx] ? PROBLEMS[idx].answer : 0;
        if (typeof submitted !== 'number' || isNaN(submitted)) return null;
        for (var i = 0; i < list.length; i++) {
            var m = list[i];
            var tol = Math.min(0.01 * Math.abs(m.v), 0.25 * Math.abs(m.v - key));
            if (Math.abs(submitted - m.v) <= tol && Math.abs(submitted - m.v) < Math.abs(submitted - key)) return m;
        }
        return null;
    }

    function problemTopic(idx) {
        var p = PROBLEMS[idx];
        if (!p) return '';
        return eqLang() === 'es' ? p.topicEs : p.topic;
    }

    function unitText(unit) {
        if (unit === '$') return '$';
        return unit === 'units' ? eqT('unit_units') : unit;
    }

    class MathBizAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MathBiz: Business Mathematics Lab';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    maxPossible: 100,
                    correctCount: 0,
                    answeredCount: 0,
                    partialCount: 0,
                    streak: 0,
                    bestStreak: 0,
                    scoreHistory: [],
                    errorHistory: [],
                    pointsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    answer: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, PROBLEMS.length - 1);
            this._paintProblem(idx);

            var answerInput = document.getElementById('answerInput');
            if (answerInput) { answerInput.value = ''; answerInput.disabled = (state.currentPeriod || 1) > PROBLEMS.length; }

            this._lastFb = null;
            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }

        _paintStatic() {
            var c1 = document.getElementById('scoreChart');
            if (c1) { c1.setAttribute('role', 'img'); c1.setAttribute('aria-label', eqT('chart_score_alt')); }
            var c2 = document.getElementById('errorChart');
            if (c2) { c2.setAttribute('role', 'img'); c2.setAttribute('aria-label', eqT('chart_error_alt')); }
        }

        _repaint() {
            this._paintStatic();
            if (typeof this._shownIdx === 'number') this._paintProblem(this._shownIdx);
            if (this._lastFb) this._paintFeedback(this._lastFb);
        }

        _paintFeedback(fb) {
            var problem = PROBLEMS[fb.idx];
            var isEs = eqLang() === 'es';
            var localHint = isEs ? problem.hintEs : problem.hint;
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackTitle = document.getElementById('feedbackTitle');
            var feedbackText = document.getElementById('feedbackText');
            var feedbackDetail = document.getElementById('feedbackDetail');
            if (!feedbackPanel) return;
            feedbackPanel.style.display = 'block';
            feedbackPanel.className = 'mathbiz-sim-feedback mathbiz-sim-feedback-' + fb.grade;
            var head = eqT('feedback_problem').split('{n}').join(String(fb.idx + 1)) + ' — ';
            var methodLine = '';
            if (fb.method && !fb.method.full && fb.grade !== 'correct') {
                methodLine = '<br>' + eqT('feedback_method').split('{method}').join(eqT(fb.method.k));
            }
            if (fb.grade === 'correct') {
                if (feedbackTitle) feedbackTitle.textContent = '✅ ' + head + eqT('feedback_correct');
                if (feedbackText) feedbackText.textContent = eqT('feedback_perfect');
            } else if (fb.grade === 'partial') {
                if (feedbackTitle) feedbackTitle.textContent = '⚠️ ' + head + eqT('feedback_partial');
                if (feedbackText) feedbackText.innerHTML = eqT('feedback_close') + methodLine + '<br>' + localHint;
            } else {
                if (feedbackTitle) feedbackTitle.textContent = '❌ ' + head + eqT('feedback_incorrect');
                if (feedbackText) feedbackText.innerHTML = eqT('feedback_review') + methodLine + '<br>' + localHint;
            }
            if (feedbackDetail) {
                var u = unitText(problem.unit);
                var fmt = function(n) { return problem.unit === '$' ? '$' + n.toLocaleString() : n.toLocaleString() + ' ' + u; };
                feedbackDetail.textContent = eqT('feedback_your_answer') + ': ' + fmt(fb.submitted) +
                    ' | ' + eqT('feedback_correct_answer') + ': ' + fmt(problem.answer) +
                    ' | ' + eqT('feedback_points') + ': ' + fb.points + '/' + problem.maxPoints;
            }
        }

        _paintProblem(idx) {
            this._shownIdx = idx;
            var problem = PROBLEMS[idx];
            var isEs = eqLang() === 'es';

            var badge = document.getElementById('topicBadge');
            if (badge) badge.textContent = isEs ? problem.topicEs : problem.topic;

            var titleEl = document.getElementById('problemTitle');
            if (titleEl) titleEl.textContent = isEs ? problem.titleEs : problem.title;

            var descEl = document.getElementById('problemDescription');
            if (descEl) descEl.innerHTML = isEs ? problem.descriptionEs : problem.description;

            var formulaEl = document.getElementById('formulaBox');
            if (formulaEl) formulaEl.textContent = (isEs && problem.formulaEs) ? problem.formulaEs : problem.formula;

            var unitEl = document.getElementById('unitLabel');
            if (unitEl) unitEl.textContent = problem.unit === '$' ? '$' : '';
        }

        validateDecisions(decisions) {
            var input = document.getElementById('answerInput');
            if (input) decisions.answer = parseFloat(input.value);

            if (isNaN(decisions.answer)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('answer_required'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min(state.currentPeriod - 1, PROBLEMS.length - 1);
            var problem = PROBLEMS[idx];
            var correct = problem.answer;
            var submitted = d.answer;
            var errorPct = Math.abs(submitted - correct) / Math.abs(correct) * 100;
            // band edges compared on the error rounded to 9 decimals, so an answer exactly 2, 5 or 15 percent off
            // lands inside its band whatever the floating point noise
            var bandErr = Math.round(errorPct * 1e9) / 1e9;
            var points = 0;
            var grade = 'incorrect';

            if (bandErr <= 2) {
                points = problem.maxPoints;
                grade = 'correct';
                ds.correctCount += 1;
                ds.streak += 1;
            } else if (bandErr <= 5) {
                points = Math.round(problem.maxPoints * 0.7);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else if (bandErr <= 15) {
                points = Math.round(problem.maxPoints * 0.3);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else {
                points = 0;
                grade = 'incorrect';
                ds.streak = 0;
            }

            if (ds.streak > ds.bestStreak) ds.bestStreak = ds.streak;

            ds.answeredCount = (ds.answeredCount || 0) + 1;
            ds.score += points;
            ds.scoreHistory.push(ds.score);
            ds.errorHistory.push(Math.round(errorPct * 100) / 100);
            ds.pointsHistory.push(points);

            // overallScore is the running percent of points earned versus points possible in the problems seen so far, matching the percentage getPerformanceSummary reports at completion
            var maxSoFar = 0;
            for (var mi = 0; mi <= idx; mi++) { maxSoFar += PROBLEMS[mi].maxPoints; }
            var overallScore = maxSoFar > 0 ? Math.round(100 * ds.score / maxSoFar) : 0;
            overallScore = Math.max(0, Math.min(100, overallScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // the result of this problem stays on screen, and the next problem is painted now, so the problem shown
            // is always the one the next submission scores
            this._lastFb = { idx: idx, grade: grade, submitted: submitted, points: points, method: detectMethod(idx, submitted) };
            this._paintFeedback(this._lastFb);
            var isLast = state.currentPeriod >= PROBLEMS.length;
            var ansInput = document.getElementById('answerInput');
            if (!isLast) {
                this._paintProblem(idx + 1);
                if (ansInput) { ansInput.value = ''; ansInput.disabled = false; }
            } else if (ansInput) {
                ansInput.disabled = true;
            }

            return {
                period: state.currentPeriod,
                topic: problem.topic,
                submitted: submitted,
                correct: correct,
                errorPct: Math.round(errorPct * 100) / 100,
                points: points,
                maxPoints: problem.maxPoints,
                grade: grade,
                cumulativeScore: ds.score
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score');
            uiManager.bind('maxScoreDisplay', 'domainState.maxPossible');
            uiManager.bind('accuracyDisplay', 'domainState.correctCount', function(v) {
                var st = window.mySimulation ? window.mySimulation.state : null;
                var total = st && st.domainState ? (st.domainState.answeredCount || 0) : 0;
                if (total <= 0) return '0%';
                return Math.round((v / total) * 100) + '%';
            });
            uiManager.bind('streakDisplay', 'domainState.streak');
            var self = this;
            this._paintStatic();
            if (!window.__mathbizRepaintBound) {
                window.__mathbizRepaintBound = true;
                var repaint = function() { try { if (window.__mathbizAdapter) window.__mathbizAdapter._repaint(); } catch (e) {} };
                document.addEventListener('express:langchanged', function() { setTimeout(repaint, 0); });
                try {
                    var bus = window.mySimulation && window.mySimulation.eventBus;
                    if (bus && typeof bus.on === 'function') {
                        bus.on('language:changed', function() { setTimeout(repaint, 0); });
                        bus.on('period:undone', function() {
                            setTimeout(function() { try { var a = window.__mathbizAdapter; if (a && window.mySimulation) a._updateBriefing(window.mySimulation.state); } catch (e) {} }, 0);
                        });
                    }
                } catch (e) {}
            }
            window.__mathbizAdapter = self;
        }

        formatCompletionMessage(summary) {
