            var insights = (s.insights || []).map(function(i) { return '<li>' + i + '</li>'; }).join('');
            var questions = (s.questions || []).map(function(q) { return '<li>' + q + '</li>'; }).join('');
            var pts = ((s.totalPoints != null) ? s.totalPoints : 0) + ' / ' + ((s.maxPoints != null) ? s.maxPoints : 0);
            var exact = ((s.correctCount != null) ? s.correctCount : 0) + ' / ' + PROBLEMS.length;
            var rec = insights ? '<hr><div style="text-align:left"><strong>' + t('complete_recommendations') + '</strong><ul>' + insights + '</ul></div>' : '';
            var qs = questions ? '<div style="text-align:left"><strong>' + t('complete_questions') + '</strong><ol>' + questions + '</ol></div>' : '';
            return '<div style="text-align:center;padding:12px"><div style="font-size:2.6rem;font-weight:800;color:#1a237e">' + pct + '%</div>' +
