        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};

            var totalPoints = 0;
            var maxPoints = 0;
            var correctCount = 0;

            history.forEach(function(h) {
                if (h.results) {
                    totalPoints += h.results.points || 0;
                    maxPoints += h.results.maxPoints || 0;
                    if (h.results.grade === 'correct') correctCount += 1;
                }
            });

            var t = eqT;
            var pct = maxPoints > 0 ? (totalPoints / maxPoints) * 100 : 0;
            var tier = 'needs_practice';
            if (pct >= 90) tier = 'excellent';
            else if (pct >= 75) tier = 'good';
            else if (pct >= 60) tier = 'satisfactory';
            var performanceLabel = t('perf_' + tier);

            var insights = [];
            insights.push(t('insight_' + tier));

            // turning point: the problem that cost the most points in this run
            var worst = null;
            history.forEach(function(h) {
                if (!h.results) return;
                var lost = (h.results.maxPoints || 0) - (h.results.points || 0);
                if (lost > 0 && (!worst || lost > worst.lost)) worst = { lost: lost, max: h.results.maxPoints, idx: (h.results.period || h.period || 1) - 1 };
            });
            if (worst) {
                insights.push(t('insight_turning_point').split('{n}').join(String(worst.idx + 1)).split('{topic}').join(problemTopic(worst.idx))
                    .split('{lost}').join(String(worst.lost)).split('{max}').join(String(worst.max)));
            }

            // wrong methods recognised from the answers actually given
            history.forEach(function(h) {
                if (!h.results) return;
                var idx = (h.results.period || h.period || 1) - 1;
                var m = detectMethod(idx, h.results.submitted);
                if (!m) return;
                var key = (m.full && h.results.grade === 'correct') ? 'insight_method_full' : 'insight_method';
                insights.push(t(key).split('{n}').join(String(idx + 1)).split('{method}').join(t(m.k)));
            });

            var weakTopics = [];
            history.forEach(function(h) {
                if (h.results && h.results.errorPct > 15) {
                    var wi = (h.results.period || h.period || 1) - 1;
                    weakTopics.push(PROBLEMS[wi] ? problemTopic(wi) : h.results.topic);
                }
            });
            if (weakTopics.length > 0) {
                insights.push(t('insight_topics_review').split('{topics}').join(weakTopics.join(', ')));
            }

            var questions = [t('debrief_q1'), t('debrief_q2'), t('debrief_q3')];
            var pctR = Math.round(pct);

            return {
                totalPoints: totalPoints,
                maxPoints: maxPoints,
                percentage: pctR,
                overallScore: pctR,
                totalScore: pctR,
                composite: pctR,
                score: pctR,
                correctCount: correctCount,
                performance: tier,
                performanceKey: 'perf_' + tier,
                performanceLabel: performanceLabel,
                insights: insights,
                questions: questions
            };
        }

        getHint(state, results) {
